import { NextResponse } from 'next/server';
import { getMember, deny } from '@/lib/integrations/auth';
import { makeIdeaCover, CoverError } from '@/lib/ideas/cover';

// Sets an idea's cover from the server: generated by the workspace's image model from the idea's title, hook and
// angle, or copied from a picture the web already has (a reference thumbnail). See lib/ideas/cover. The idea row is
// saved on the member's own session so RLS decides who may change it.
export const maxDuration = 120;

export async function POST(request: Request) {
  const m = await getMember();
  if (!m) return deny('Sign in to set a cover.', 401);
  if (m.ctx.role === 'editor') return deny('Editors cannot change idea covers.');
  const body = await request.json().catch(() => ({}));
  const ideaId = typeof body?.ideaId === 'string' ? body.ideaId : '';
  if (!ideaId) return deny('Which idea?', 400);
  try {
    const out = await makeIdeaCover({
      ideaId, ws: m.ctx.workspace_id, member: m, mode: body?.mode === 'url' ? 'url' : 'generate',
      style: String(body?.style || 'photo'), prompt: String(body?.prompt || ''), url: String(body?.url || ''), onlyIfMissing: body?.onlyIfMissing === true,
    });
    return NextResponse.json(out);
  } catch (err) {
    const e = err as CoverError;
    return deny(e.message || 'The cover could not be made.', e instanceof CoverError ? e.status : 502);
  }
}
